mapper.select:
SELECT 
FROM hm_welfare_ranking
WHERE stat_period = #{statPeriod}
  AND stat_date = #{statDate}
  AND user_id = #{userId}
LIMIT 1

SELECT 
FROM hm_welfare_ranking
WHERE stat_period = #{statPeriod}
  AND stat_date = #{statDate}
ORDER BY ranking ASC
LIMIT #{limit}

mapper.delete:
DELETE FROM hm_welfare_ranking
WHERE stat_period = #{statPeriod}
  AND stat_date = #{statDate}
